import{_ as u,C as s,o as g,c as m,j as t,a,E as o,a8 as b}from"./chunks/framework.27XeWUA0.js";const n="/schedule-dashboard/thumbs/yt/21tuT-e4NVo-640.webp",v="/schedule-dashboard/thumbs/yt/21tuT-e4NVo-1280.webp",r="/schedule-dashboard/thumbs/yt/WJTQBENv0KI-640.webp",f="/schedule-dashboard/thumbs/yt/WJTQBENv0KI-1280.webp",i="/schedule-dashboard/thumbs/yt/u7fsyrXsPBE-640.webp",y="/schedule-dashboard/thumbs/yt/u7fsyrXsPBE-1280.webp",l="/schedule-dashboard/thumbs/yt/jDwc0aXTAFg-640.webp",k="/schedule-dashboard/thumbs/yt/jDwc0aXTAFg-1280.webp",h="/schedule-dashboard/thumbs/yt/BT1Mo-fD-g0-640.webp",_="/schedule-dashboard/thumbs/yt/BT1Mo-fD-g0-1280.webp",c="/schedule-dashboard/thumbs/yt/EaOit1mmR9g-640.webp",T="/schedule-dashboard/thumbs/yt/EaOit1mmR9g-1280.webp",d="/schedule-dashboard/thumbs/yt/P5QCrpdr9gU-640.webp",A="/schedule-dashboard/thumbs/yt/P5QCrpdr9gU-1280.webp",Q=JSON.parse('{"title":"AI Digest · Mon 09 Nov 2026","description":"","frontmatter":{"aside":false,"outline":false},"headers":[],"params":{"date":"2026-11-09","routine":"digest"},"relativePath":"digest/2026-11-09.md","filePath":"digest/[date].md"}'),E={name:"digest/2026-11-09.md"},I=n+" 640w, "+v+" 1280w",C=r+" 640w, "+f+" 1280w",N=i+" 640w, "+y+" 1280w",P=l+" 640w, "+k+" 1280w",B=h+" 640w, "+_+" 1280w",R=c+" 640w, "+T+" 1280w",x=d+" 640w, "+A+" 1280w",S={id:"ai-digest-·-mon-09-nov-2026",tabindex:"-1"};function D(M,e,q,W,X,O){const p=s("Badge"),w=s("DayFilter");return g(),m("div",null,[t("h1",S,[e[0]||(e[0]=a("AI Digest · Mon 09 Nov 2026 ",-1)),o(p,{type:"tip",text:"7"}),e[1]||(e[1]=a()),e[2]||(e[2]=t("a",{class:"header-anchor",href:"#ai-digest-·-mon-09-nov-2026","aria-label":'Permalink to "AI Digest · Mon 09 Nov 2026 <Badge type="tip" text="7" />"'},"​",-1))]),e[3]||(e[3]=t("p",{class:"sub"},"AI Engineer + Better Stack daily digest — 9 Nov 2026 · run date Mon 09 Nov 2026 · 7 videos",-1)),e[4]||(e[4]=t("div",{class:"overview"},[t("p",null,[t("strong",null,"AI Engineer:"),a(` 6 new talks in the last 24 hours. The freshest are McKinsey on what the top 20–25% of companies do differently with AI coding (9 Nov, 1:30 AM IST) and Ramp's eval playbook for its bookkeeping agent (12:30 AM IST). The ones most worth watching are Ramp's evals, AlixPartners' post-mortem of how Claude Code missed $800K in a contract analysis, and Citadel Securities' design for a company "world model". The Range talk is a longer version of one posted on 12 Oct, so it's mostly a repeat. The Undo talk had no fetchable transcript, so its entry comes from the description only.`)]),t("p",null,[t("strong",null,"Better Stack:"),a(" 1 new video (8 Nov, 5:45 PM IST) on Microsoft's open-source TokenEconomizer plugin, which cut coding agent costs 18–31% on SWE-bench. Token-saving tools are a well-worn Better Stack topic, but this one works differently (it learns from past sessions in a repo).")])],-1)),o(w),e[5]||(e[5]=b('<div class="grid cards2"><article class="it full" id="v-21tuT-e4NVo" data-title="What the Top Companies Do Differently With AI Coding - Martin Harrysson &amp; Prakhar Dixit, McKinsey" data-channel="AI Engineer" data-verdict="skim"><a class="th" href="https://www.youtube.com/watch?v=21tuT-e4NVo" target="_blank" rel="noopener"><img src="'+n+'" srcset="'+I+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">AI Engineer</span><span class="chip warn">repeat</span><span class="chip v-skim">skim</span><h3><a href="https://www.youtube.com/watch?v=21tuT-e4NVo" target="_blank" rel="noopener">What the Top Companies Do Differently With AI Coding - Martin Harrysson &amp; Prakhar Dixit, McKinsey</a></h3><div class="meta">AI Engineer · Martin Harrysson, Prakhar Dixit and Shilpa, McKinsey · uploaded 9 Nov, 1:30 AM IST · 20:28</div><div class="verdict v-skim"><b>Verdict:</b> skim from 5:10 — a useful consultant&#39;s map of what top enterprises change (pods, day-long loops, skill curation), but the quality and bottleneck points are well-worn ground.</div><div class="repeat">🔁 Repeat: &#39;coding agents in production&#39; — seen 72 times before. New here: McKinsey&#39;s survey split (only the top 20–25% of large companies see 2x end-to-end gains) and what those companies change in team shape and process.</div><div class="repeat">🔁 Repeat: &#39;AI-generated code validation&#39; — seen 33 times before. New here: McKinsey says defects are rising even per developer and per PR, not just because there are more commits.</div><div class="repeat">🔁 Repeat: &#39;agent skills&#39; — seen 21 times before. New here: the problem is curating skills, not finding them (one client found 1,700 downloadable skills just for writing a PRD).</div><div class="repeat">🔁 Repeat: &#39;AI ROI measurement&#39; — seen 13 times before. New here: little; a few clients are trying AI to score the value of the work being built.</div><div class="sh">Where large companies are</div><ul><li><strong>Out of the trough, for some:</strong> A late-2025 survey showed a big gap between expectations and the modest gains most large companies reported. A re-survey of a few hundred enterprises a few months ago found the top 20–25% now getting real 2x end-to-end improvements, not just 10–20% faster coding (<a href="https://www.youtube.com/watch?v=21tuT-e4NVo&amp;t=83s" target="_blank" rel="noopener">1:23</a>–<a href="https://www.youtube.com/watch?v=21tuT-e4NVo&amp;t=212s" target="_blank" rel="noopener">3:32</a>)</li><li><strong>Four levers:</strong> Operating model, talent, tech and change management. Adding more tools to the same process &quot;is just not working&quot;; the flow itself has to be redesigned (<a href="https://www.youtube.com/watch?v=21tuT-e4NVo&amp;t=212s" target="_blank" rel="noopener">3:32</a>–<a href="https://www.youtube.com/watch?v=21tuT-e4NVo&amp;t=310s" target="_blank" rel="noopener">5:10</a>)</li></ul><div class="sh">What the leaders change</div><ul><li><strong>No more two-week sprints:</strong> Teams are moving to Kanban-style one- to two-day loops where agents run &quot;the night shift&quot; and humans validate in the morning. Human review checkpoints are removed as confidence grows, and the loops are spreading from build and test into product and release. Standardized templates for PRDs and specs are a prerequisite (<a href="https://www.youtube.com/watch?v=21tuT-e4NVo&amp;t=310s" target="_blank" rel="noopener">5:10</a>–<a href="https://www.youtube.com/watch?v=21tuT-e4NVo&amp;t=435s" target="_blank" rel="noopener">7:15</a>)</li><li><strong>Smaller pods, merged roles:</strong> Teams shrink to pods of two to four people (more teams, not fewer people), and layered roles collapse into roughly a &quot;definer&quot; (product) and a &quot;builder&quot; (dev and QA) (<a href="https://www.youtube.com/watch?v=21tuT-e4NVo&amp;t=435s" target="_blank" rel="noopener">7:15</a>–<a href="https://www.youtube.com/watch?v=21tuT-e4NVo&amp;t=493s" target="_blank" rel="noopener">8:13</a>)</li><li><strong>Tooling is &quot;solved&quot;, context isn&#39;t:</strong> The edge is the semantic layer, meaning the knowledge locked in the heads of 20-year veterans, plus a trust layer for governance and security (repeat) (<a href="https://www.youtube.com/watch?v=21tuT-e4NVo&amp;t=493s" target="_blank" rel="noopener">8:13</a>–<a href="https://www.youtube.com/watch?v=21tuT-e4NVo&amp;t=564s" target="_blank" rel="noopener">9:24</a>)</li><li><strong>Scaling past pilots, and curating skills:</strong> Pilots that claim 10x in six days don&#39;t scale to thousands of engineers without the operating model, team structure and an AI FinOps view of agent costs. On skills, curation is the bottleneck: one client found 1,700 downloadable skills just for writing a PRD (<a href="https://www.youtube.com/watch?v=21tuT-e4NVo&amp;t=564s" target="_blank" rel="noopener">9:24</a>–<a href="https://www.youtube.com/watch?v=21tuT-e4NVo&amp;t=695s" target="_blank" rel="noopener">11:35</a>)</li></ul><div class="sh">Quality and the new bottlenecks</div><ul><li><strong>Faster code, worse quality:</strong> Their data shows bugs and incidents rising even per developer and per PR. Their fix is curated &quot;golden examples&quot; (not the average of your codebase) and encoded quality rules at every checkpoint from PRD to merge, instead of one gate at the end (<a href="https://www.youtube.com/watch?v=21tuT-e4NVo&amp;t=695s" target="_blank" rel="noopener">11:35</a>–<a href="https://www.youtube.com/watch?v=21tuT-e4NVo&amp;t=847s" target="_blank" rel="noopener">14:07</a>)</li><li><strong>The bottleneck moves up, down and sideways:</strong> With build and test compressed, the slow parts become writing requirements, release frequency, and &quot;sideways&quot; teams like risk, compliance and design. One bank had color and color-blind accessibility rules that also had to be encoded into the agents (<a href="https://www.youtube.com/watch?v=21tuT-e4NVo&amp;t=847s" target="_blank" rel="noopener">14:07</a>–<a href="https://www.youtube.com/watch?v=21tuT-e4NVo&amp;t=967s" target="_blank" rel="noopener">16:07</a>)</li><li><strong>Measuring impact and a near-term cheat code:</strong> Measurement is still mostly old metrics. Halving pod size and doubling the team count while leaders keep planning as before gives quick acceleration. Leaders are seeing 2x–3x on many metrics (<a href="https://www.youtube.com/watch?v=21tuT-e4NVo&amp;t=967s" target="_blank" rel="noopener">16:07</a>–<a href="https://www.youtube.com/watch?v=21tuT-e4NVo&amp;t=1214s" target="_blank" rel="noopener">20:14</a>)</li></ul></div></article><article class="it full" id="v-WJTQBENv0KI" data-title="How Ramp Tests Its AI Bookkeeping Agent Before Customers Do - Ryan Stevens, Ramp" data-channel="AI Engineer" data-verdict="worth"><a class="th" href="https://www.youtube.com/watch?v=WJTQBENv0KI" target="_blank" rel="noopener"><img src="'+r+'" srcset="'+C+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">AI Engineer</span><span class="chip warn">repeat</span><span class="chip v-worth">worth</span><h3><a href="https://www.youtube.com/watch?v=WJTQBENv0KI" target="_blank" rel="noopener">How Ramp Tests Its AI Bookkeeping Agent Before Customers Do - Ryan Stevens, Ramp</a></h3><div class="meta">AI Engineer · Ryan Stevens, head of applied science, Ramp · uploaded 9 Nov, 12:30 AM IST · 18:39</div><div class="verdict v-worth"><b>Verdict:</b> worth watching — a concrete, honest eval playbook with real failures and two techniques (skill ablation, roll-forward memory tests) that you rarely see shown.</div><div class="repeat">🔁 Repeat: &#39;evals for agents&#39; — seen 64 times before. New here: eval worlds built from fully synthetic businesses, a frank list of experiments that failed (including auto-tuned prompts), and &quot;roll-forward worlds&quot; for testing memory.</div><div class="repeat">🔁 Repeat: &#39;AI for finance&#39; — seen 35 times before (incl. Ramp&#39;s own talk on 4 Nov). New here: the bookkeeping agent&#39;s eval design rather than models or cost.</div><div class="sh">Designing the benchmark</div><ul><li><strong>Break the job down first:</strong> For Stack, Ramp&#39;s agent for bookkeepers, they split the job into four task types: reconciliation, data entry, variance analysis, and schedules and accruals. They sat with accounting firms to map how each task is done end to end, e.g. tying the ERP&#39;s payables ledger to the bills system row by row (<a href="https://www.youtube.com/watch?v=WJTQBENv0KI&amp;t=47s" target="_blank" rel="noopener">0:47</a>–<a href="https://www.youtube.com/watch?v=WJTQBENv0KI&amp;t=200s" target="_blank" rel="noopener">3:20</a>)</li><li><strong>Synthetic businesses:</strong> With no users yet, they built synthetic companies with Mercor (one is a multi-channel D2C brand selling via Shopify and Amazon), with a full ERP, vendor and customer lists and payables, so agents can be back-tested on the same frozen data every day (<a href="https://www.youtube.com/watch?v=WJTQBENv0KI&amp;t=266s" target="_blank" rel="noopener">4:26</a>–<a href="https://www.youtube.com/watch?v=WJTQBENv0KI&amp;t=345s" target="_blank" rel="noopener">5:45</a>)</li><li><strong>Grade the output, not the path:</strong> Each task has 10–20 criteria checked on the final output, not on which tools or skills were called. Building this took 4–6 months before launch, which he says is typical outside areas the frontier models already target (<a href="https://www.youtube.com/watch?v=WJTQBENv0KI&amp;t=428s" target="_blank" rel="noopener">7:08</a>–<a href="https://www.youtube.com/watch?v=WJTQBENv0KI&amp;t=554s" target="_blank" rel="noopener">9:14</a>)</li></ul><div class="sh">What the evals revealed</div><ul><li><strong>Accuracy vs pass@k:</strong> Accuracy gives partial credit (4 of 6 criteria is 67%), while pass@k is all-or-nothing, which suits accounting where one wrong step kills trust. Opus models score best, but pass@1 is still low, so the benchmark isn&#39;t saturated and harness work still pays off (<a href="https://www.youtube.com/watch?v=WJTQBENv0KI&amp;t=554s" target="_blank" rel="noopener">9:14</a>–<a href="https://www.youtube.com/watch?v=WJTQBENv0KI&amp;t=678s" target="_blank" rel="noopener">11:18</a>)</li><li><strong>Models fail on reasoning:</strong> Most failures had all the data and reasoned wrongly; gathering the right files is easy in accounting. So &quot;the models just ain&#39;t that smart&quot; yet (<a href="https://www.youtube.com/watch?v=WJTQBENv0KI&amp;t=678s" target="_blank" rel="noopener">11:18</a>–<a href="https://www.youtube.com/watch?v=WJTQBENv0KI&amp;t=738s" target="_blank" rel="noopener">12:18</a>)</li><li><strong>What didn&#39;t work:</strong> GEPA, auto-tuned prompts and auto-researched skills gave no gain. He argues hill-climbing in text space lacks the gradient that makes Karpathy-style auto-research work on ML training (<a href="https://www.youtube.com/watch?v=WJTQBENv0KI&amp;t=738s" target="_blank" rel="noopener">12:18</a>–<a href="https://www.youtube.com/watch?v=WJTQBENv0KI&amp;t=816s" target="_blank" rel="noopener">13:36</a>)</li></ul><div class="sh">What worked</div><ul><li><strong>Skill ablation:</strong> Leave-one-out tests of each skill against a no-skill baseline showed which skills help or hurt, giving a list of skills to delete or compress to save context (<a href="https://www.youtube.com/watch?v=WJTQBENv0KI&amp;t=816s" target="_blank" rel="noopener">13:36</a>–<a href="https://www.youtube.com/watch?v=WJTQBENv0KI&amp;t=901s" target="_blank" rel="noopener">15:01</a>)</li><li><strong>Roll-forward worlds for memory:</strong> The same task runs in two periods; the agent writes a memory after the first and reads it in the second, which tests whether it learns implicit customer rules. The memory-writing prompt mattered a lot, and this was one of their biggest gains (<a href="https://www.youtube.com/watch?v=WJTQBENv0KI&amp;t=901s" target="_blank" rel="noopener">15:01</a>–<a href="https://www.youtube.com/watch?v=WJTQBENv0KI&amp;t=1021s" target="_blank" rel="noopener">17:01</a>)</li><li><strong>Background regression runs, not CI gates:</strong> Agent evals are too non-deterministic to gate CI. Instead, tagged cases run on a schedule, a background agent triages regressions, and the team gets a Slack message saying what probably broke (<a href="https://www.youtube.com/watch?v=WJTQBENv0KI&amp;t=1021s" target="_blank" rel="noopener">17:01</a>–<a href="https://www.youtube.com/watch?v=WJTQBENv0KI&amp;t=1119s" target="_blank" rel="noopener">18:39</a>)</li></ul></div></article><article class="it full" id="v-u7fsyrXsPBE" data-title="Claude Code Looked Right but Missed $800K - Natalia Connolly &amp; Kevin Madura, AlixPartners" data-channel="AI Engineer" data-verdict="worth"><a class="th" href="https://www.youtube.com/watch?v=u7fsyrXsPBE" target="_blank" rel="noopener"><img src="'+i+'" srcset="'+N+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">AI Engineer</span><span class="chip warn">repeat</span><span class="chip v-worth">worth</span><h3><a href="https://www.youtube.com/watch?v=u7fsyrXsPBE" target="_blank" rel="noopener">Claude Code Looked Right but Missed $800K - Natalia Connolly &amp; Kevin Madura, AlixPartners</a></h3><div class="meta">AI Engineer · Natalia Connolly and Kevin Madura, AlixPartners · uploaded 8 Nov, 11:30 PM IST · 18:32</div><div class="verdict v-worth"><b>Verdict:</b> worth watching — a rare, specific post-mortem of where a coding agent silently got finance numbers wrong, with fixes you can reuse.</div><div class="repeat">🔁 Repeat: &#39;AI for finance&#39; — seen 35 times before. New here: a post-merger procurement case with specific failure modes.</div><div class="repeat">🔁 Repeat: &#39;context engineering&#39; — seen 25 times before. New here: little beyond &quot;business context is still king&quot;.</div><div class="repeat">🔁 Repeat: &#39;structured extraction&#39; — seen 6 times before. New here: the five-stage contract pipeline and the restated-amendment trap.</div><div class="sh">The case</div><ul><li><strong>40,000 contracts after a merger:</strong> A large healthcare company bought a smaller niche player, leaving hundreds of vendors, 40,000+ contract documents and unlinked databases. Procurement needed renegotiation savings and deadlines, each traced to a contract page or invoice line (<a href="https://www.youtube.com/watch?v=u7fsyrXsPBE&amp;t=52s" target="_blank" rel="noopener">0:52</a>–<a href="https://www.youtube.com/watch?v=u7fsyrXsPBE&amp;t=150s" target="_blank" rel="noopener">2:30</a>)</li><li><strong>Answers that looked right:</strong> Claude Code&#39;s first answers were well formatted. Spend and contract counts were correct, but total contract value was off by about $800,000, and the deadline to stop the soonest contract auto-renewing came back as 1 December when it was 1 November (<a href="https://www.youtube.com/watch?v=u7fsyrXsPBE&amp;t=150s" target="_blank" rel="noopener">2:30</a>–<a href="https://www.youtube.com/watch?v=u7fsyrXsPBE&amp;t=209s" target="_blank" rel="noopener">3:29</a>)</li></ul><div class="sh">Why contract data is messy</div><ul><li><strong>Silent failures and orphans:</strong> Very long contracts can time out in preprocessing and never reach the database. An amendment not linked to its parent caused the $800K miss (<a href="https://www.youtube.com/watch?v=u7fsyrXsPBE&amp;t=209s" target="_blank" rel="noopener">3:29</a>–<a href="https://www.youtube.com/watch?v=u7fsyrXsPBE&amp;t=270s" target="_blank" rel="noopener">4:30</a>)</li><li><strong>Restated values and split tables:</strong> If two amendments each restate the total, summing the numbers gives about $17M when the right answer is the latest amendment&#39;s $7M. Rate tables that run across pages lose their headers (<a href="https://www.youtube.com/watch?v=u7fsyrXsPBE&amp;t=270s" target="_blank" rel="noopener">4:30</a>–<a href="https://www.youtube.com/watch?v=u7fsyrXsPBE&amp;t=346s" target="_blank" rel="noopener">5:46</a>)</li><li><strong>Five-stage pipeline:</strong> Two weeks building it (OCR, classification as MSA, amendment or NDA, terms, rates and spend extraction including cross-page tables, mapping to spend categories), then 40,000+ contracts ran overnight. Charts went through DSPy as page images to get structured output (<a href="https://www.youtube.com/watch?v=u7fsyrXsPBE&amp;t=346s" target="_blank" rel="noopener">5:46</a>–<a href="https://www.youtube.com/watch?v=u7fsyrXsPBE&amp;t=506s" target="_blank" rel="noopener">8:26</a>)</li><li><strong>Custom tools with business rules:</strong> Claude Code built deal-specific tools like &quot;get rate card page&quot; or &quot;get vendor spend&quot; with the business logic baked into the code rather than the prompt, later packaged into MCP servers, with every other operation blocked (<a href="https://www.youtube.com/watch?v=u7fsyrXsPBE&amp;t=506s" target="_blank" rel="noopener">8:26</a>–<a href="https://www.youtube.com/watch?v=u7fsyrXsPBE&amp;t=674s" target="_blank" rel="noopener">11:14</a>)</li></ul><div class="sh">Lessons</div><ul><li><strong>Wrong date, orphaned amendments:</strong> The date had to come from the renewal clause, not the termination clause. Contract management systems are rarely maintained, so Claude reads contracts bottom-up to rebuild the MSA, SOW and amendment hierarchy (<a href="https://www.youtube.com/watch?v=u7fsyrXsPBE&amp;t=674s" target="_blank" rel="noopener">11:14</a>–<a href="https://www.youtube.com/watch?v=u7fsyrXsPBE&amp;t=805s" target="_blank" rel="noopener">13:25</a>)</li><li><strong>Access errors look like zeros:</strong> When access to one entity&#39;s data failed, Claude read the result as a $0 invoice. Clear error feedback lets it recover, switch to another source or flag a human (<a href="https://www.youtube.com/watch?v=u7fsyrXsPBE&amp;t=805s" target="_blank" rel="noopener">13:25</a>–<a href="https://www.youtube.com/watch?v=u7fsyrXsPBE&amp;t=877s" target="_blank" rel="noopener">14:37</a>)</li><li><strong>De-duplicate and know the business:</strong> Parallel agents ran each savings lever, then a DSPy-based reconciliation step removed double-counted savings. Good recommendations got rejected because management had already started them 3 months earlier, so that context has to be stored where the agent will see it (<a href="https://www.youtube.com/watch?v=u7fsyrXsPBE&amp;t=877s" target="_blank" rel="noopener">14:37</a>–<a href="https://www.youtube.com/watch?v=u7fsyrXsPBE&amp;t=1112s" target="_blank" rel="noopener">18:32</a>)</li></ul></div></article><article class="it full" id="v-jDwc0aXTAFg" data-title="Your Company Has No Model of Itself. Agents Can Build One - Joao Wenzel, Citadel Securities" data-channel="AI Engineer" data-verdict="worth"><a class="th" href="https://www.youtube.com/watch?v=jDwc0aXTAFg" target="_blank" rel="noopener"><img src="'+l+'" srcset="'+P+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">AI Engineer</span><span class="chip warn">repeat</span><span class="chip v-worth">worth</span><h3><a href="https://www.youtube.com/watch?v=jDwc0aXTAFg" target="_blank" rel="noopener">Your Company Has No Model of Itself. Agents Can Build One - Joao Wenzel, Citadel Securities</a></h3><div class="meta">AI Engineer · Joao Wenzel, Citadel Securities · uploaded 8 Nov, 12:30 PM IST · 18:56</div><div class="verdict v-worth"><b>Verdict:</b> worth watching — an original, well-argued design for company-level agent memory, with real back-test numbers rather than a vendor pitch.</div><div class="repeat">🔁 Repeat: &#39;agent memory&#39; — seen 19 times before. New here: institutional memory framed as a robotics-style state estimator with a back-tested prediction step.</div><div class="repeat">🔁 Repeat: &#39;context graph&#39; — seen 4 times before. New here: evidence is weighted by age and source, and dead signals aren&#39;t read as zero.</div><div class="sh">The idea</div><ul><li><strong>The person who knows everything:</strong> Every company has someone who has lived through 17 reorgs and can predict how big moves will land. That person is the company&#39;s &quot;world model&quot;, and they don&#39;t scale. At Citadel Securities over two-thirds of employees write code, and leadership asked whether agents could help with strategy (<a href="https://www.youtube.com/watch?v=jDwc0aXTAFg&amp;t=22s" target="_blank" rel="noopener">0:22</a>–<a href="https://www.youtube.com/watch?v=jDwc0aXTAFg&amp;t=111s" target="_blank" rel="noopener">1:51</a>)</li><li><strong>Top-down meets bottom-up:</strong> Decks and status reports are tidy but slanted (&quot;watermelon projects&quot;: green outside, red inside). Slack, meeting notes, PRs and agent session traces are noisy but closer to the truth. The model is where the two meet (<a href="https://www.youtube.com/watch?v=jDwc0aXTAFg&amp;t=111s" target="_blank" rel="noopener">1:51</a>–<a href="https://www.youtube.com/watch?v=jDwc0aXTAFg&amp;t=185s" target="_blank" rel="noopener">3:05</a>)</li><li><strong>Borrow the state estimator:</strong> As in robotics, a belief gets fuzzier the longer it goes without supporting evidence and firms up when new evidence arrives. Each update weighs how old the signal is, how trustworthy its source is, and whether other sources agree (<a href="https://www.youtube.com/watch?v=jDwc0aXTAFg&amp;t=185s" target="_blank" rel="noopener">3:05</a>–<a href="https://www.youtube.com/watch?v=jDwc0aXTAFg&amp;t=246s" target="_blank" rel="noopener">4:06</a>)</li></ul><div class="sh">The loop: update, age, observe, grade, correct</div><ul><li><strong>Getting data out of a deck:</strong> Parsing the PowerPoint XML can&#39;t tell you what &quot;green&quot; is, and a vision model squints at pasted screenshots. Combining both gives the true picture, and records are tracked month to month so a renamed project is still linked to &quot;Northstar&quot; (<a href="https://www.youtube.com/watch?v=jDwc0aXTAFg&amp;t=246s" target="_blank" rel="noopener">4:06</a>–<a href="https://www.youtube.com/watch?v=jDwc0aXTAFg&amp;t=441s" target="_blank" rel="noopener">7:21</a>)</li><li><strong>Update and age:</strong> Plain retrieval says &quot;green&quot; from a few Slack messages. Their record notes what was reported versus what the evidence says, never rewrites old months, and tracks every fact&#39;s age. In 3 years of data, half of delivery dates changed within 2 months, and 90% of changes moved the date later (<a href="https://www.youtube.com/watch?v=jDwc0aXTAFg&amp;t=417s" target="_blank" rel="noopener">6:57</a>–<a href="https://www.youtube.com/watch?v=jDwc0aXTAFg&amp;t=612s" target="_blank" rel="noopener">10:12</a>)</li><li><strong>Observe with specialists:</strong> Throwing the whole corpus at one model missed detail. A workflow of specialist agents reviewed by other agents more than doubled the number of useful project updates (<a href="https://www.youtube.com/watch?v=jDwc0aXTAFg&amp;t=612s" target="_blank" rel="noopener">10:12</a>–<a href="https://www.youtube.com/watch?v=jDwc0aXTAFg&amp;t=672s" target="_blank" rel="noopener">11:12</a>)</li><li><strong>Grade by back-testing:</strong> From a February snapshot compared with what happened next, statuses that were green but flagged by the agent were twice as likely to turn yellow or red (<a href="https://www.youtube.com/watch?v=jDwc0aXTAFg&amp;t=672s" target="_blank" rel="noopener">11:12</a>–<a href="https://www.youtube.com/watch?v=jDwc0aXTAFg&amp;t=732s" target="_blank" rel="noopener">12:12</a>)</li><li><strong>Correct with people:</strong> Ask stakeholders where they already work (Slack, email), and ask about rules rather than single facts so one answer fixes many outputs. Records mark what was inferred and what was confirmed (<a href="https://www.youtube.com/watch?v=jDwc0aXTAFg&amp;t=732s" target="_blank" rel="noopener">12:12</a>–<a href="https://www.youtube.com/watch?v=jDwc0aXTAFg&amp;t=797s" target="_blank" rel="noopener">13:17</a>)</li></ul><div class="sh">Bottom-up signals and use</div><ul><li><strong>Slack, PRs and agent traces:</strong> Threads become dated claims linked to evidence; opted-in agent session traces show how work really evolved. A quiet channel is like a dead speedometer, not proof of zero, so each source tracks when it last worked (<a href="https://www.youtube.com/watch?v=jDwc0aXTAFg&amp;t=797s" target="_blank" rel="noopener">13:17</a>–<a href="https://www.youtube.com/watch?v=jDwc0aXTAFg&amp;t=945s" target="_blank" rel="noopener">15:45</a>)</li><li><strong>How it&#39;s used:</strong> Leadership meetings start where the deck and the evidence disagree. Managers get a weekly read on what&#39;s stuck and what went quiet, and the record is a context layer other agents use; they&#39;re extending it to client data. Open problems are matching one client across four systems with no shared ID, and when to ask a human versus auto-apply (<a href="https://www.youtube.com/watch?v=jDwc0aXTAFg&amp;t=945s" target="_blank" rel="noopener">15:45</a>–<a href="https://www.youtube.com/watch?v=jDwc0aXTAFg&amp;t=1136s" target="_blank" rel="noopener">18:56</a>)</li></ul></div></article><article class="it full" id="v-BT1Mo-fD-g0" data-title="Your Coding Agent Can&#39;t Undo Its Own Mistakes - Tanmay Sah &amp; Dolly Sah" data-channel="AI Engineer" data-verdict="worth"><a class="th" href="https://www.youtube.com/watch?v=BT1Mo-fD-g0" target="_blank" rel="noopener"><img src="'+h+'" srcset="'+B+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">AI Engineer</span><span class="chip warn">repeat</span><span class="chip v-worth">worth</span><h3><a href="https://www.youtube.com/watch?v=BT1Mo-fD-g0" target="_blank" rel="noopener">Your Coding Agent Can&#39;t Undo Its Own Mistakes - Tanmay Sah &amp; Dolly Sah</a></h3><div class="meta">AI Engineer · Tanmay Sah and Dolly Sah (UndoBench and EvoUndo research) · uploaded 8 Nov, 1:30 PM IST · 16:38</div><div class="verdict v-worth"><b>Verdict:</b> worth watching — a fresh angle on agent reliability with a concrete number; I can&#39;t point to the best section without a transcript.</div><div class="repeat">🔁 Repeat: &#39;coding agents in production&#39; — seen 72 times before. New here: the focus on undoing an agent&#39;s actions, which hasn&#39;t come up as its own topic before.</div><p class="note">_No transcript available yet; YouTube only offered machine-translated captions and blocked every fetch attempt, and the video has no chapters. This entry is built from the description only, so there are no in-video timestamps beyond the start (<a href="https://www.youtube.com/watch?v=BT1Mo-fD-g0&amp;t=0s" target="_blank" rel="noopener">0:00</a>)._</p><div class="sh">What the description says</div><ul><li><strong>The missing capability:</strong> An agent that finishes a task can&#39;t necessarily put things back when something breaks. Git doesn&#39;t cover external API calls, runtime config or notifications, and retrying doesn&#39;t reverse side effects.</li><li><strong>The research:</strong> Their projects UndoBench and EvoUndo found that 197 of 478 changes that made an agent more capable (about 42%) also broke its ability to recover.</li><li><strong>Their approach:</strong> Capture the original state, pick the right response (retry, restore, compensate or escalate), then independently verify the result.</li></ul></div></article><article class="it full" id="v-EaOit1mmR9g" data-title="How Financial Planners With Zero Coding Experience Built Their Own Agents - Matt Ragone, Range" data-channel="AI Engineer" data-verdict="skip"><a class="th" href="https://www.youtube.com/watch?v=EaOit1mmR9g" target="_blank" rel="noopener"><img src="'+c+'" srcset="'+R+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">AI Engineer</span><span class="chip warn">repeat</span><span class="chip v-skip">skip</span><h3><a href="https://www.youtube.com/watch?v=EaOit1mmR9g" target="_blank" rel="noopener">How Financial Planners With Zero Coding Experience Built Their Own Agents - Matt Ragone, Range</a></h3><div class="meta">AI Engineer · Matt Ragone, financial planner, Range · uploaded 8 Nov, 1:30 PM IST · 16:09</div><div class="verdict v-skip"><b>Verdict:</b> skip if you saw the 12 Oct version — the same method in twice the time; otherwise skim from 6:58 for the five steps.</div><div class="repeat">🔁 Repeat: this is a longer version of the same talk AI Engineer posted on 12 Oct (&quot;We Let Our Financial Planners Write the Agents&quot;, 8:54), with the same five-step method and the same 24-skill result.</div><div class="repeat">🔁 Repeat: &#39;human-in-the-loop review&#39; — seen 37 times before; &#39;AI for finance&#39; — seen 35 times before; &#39;agent skills&#39; — seen 21 times before; &#39;AI fluency / enablement&#39; — seen 12 times before. New here: Range&#39;s cross-team &quot;AI Council&quot;, having skills ask questions before starting, and a Slack agent called Ranger.</div><div class="sh">Why planners build the agents</div><ul><li><strong>AI Council:</strong> Ragone leads AI adoption for planners at Range and sits on an &quot;AI Council&quot; with the strongest AI users from every team, so a skill one team builds can be reused by others (<a href="https://www.youtube.com/watch?v=EaOit1mmR9g&amp;t=42s" target="_blank" rel="noopener">0:42</a>–<a href="https://www.youtube.com/watch?v=EaOit1mmR9g&amp;t=148s" target="_blank" rel="noopener">2:28</a>)</li><li><strong>From chatbot to agent:</strong> Early this year they only used AI to redraft emails and check tax rules. In late January or early February Claude Cowork let an agent draft a cash flow analysis, insurance review or tax review while he&#39;s on a call with another client (repeat) (<a href="https://www.youtube.com/watch?v=EaOit1mmR9g&amp;t=148s" target="_blank" rel="noopener">2:28</a>–<a href="https://www.youtube.com/watch?v=EaOit1mmR9g&amp;t=261s" target="_blank" rel="noopener">4:21</a>)</li><li><strong>Standards came first:</strong> Their roughly 20 planners had already written down how Range delivers each kind of recommendation, so the agent could just be told to follow that document (<a href="https://www.youtube.com/watch?v=EaOit1mmR9g&amp;t=261s" target="_blank" rel="noopener">4:21</a>–<a href="https://www.youtube.com/watch?v=EaOit1mmR9g&amp;t=387s" target="_blank" rel="noopener">6:27</a>)</li></ul><div class="sh">Five steps: pick, teach, pack, test, ship</div><ul><li><strong>Pick and teach:</strong> Pick a daily or weekly workflow that&#39;s simple but manual. Show it 2–5 real past cases, including edge cases you had to correct, and narrate why, e.g. look for a $3 group-term life deduction on a pay stub (repeat) (<a href="https://www.youtube.com/watch?v=EaOit1mmR9g&amp;t=418s" target="_blank" rel="noopener">6:58</a>–<a href="https://www.youtube.com/watch?v=EaOit1mmR9g&amp;t=551s" target="_blank" rel="noopener">9:11</a>)</li><li><strong>Pack with questions and limits:</strong> Make the skill ask questions before it starts (2025 or 2026 tax year? which state? home or disability insurance focus?). Set hard limits: no skill may send anything to a client, and a certified planner reviews everything (<a href="https://www.youtube.com/watch?v=EaOit1mmR9g&amp;t=551s" target="_blank" rel="noopener">9:11</a>–<a href="https://www.youtube.com/watch?v=EaOit1mmR9g&amp;t=650s" target="_blank" rel="noopener">10:50</a>)</li><li><strong>Test and ship:</strong> Run it on 5–10 real cases, ask it &quot;how could you make yourself better?&quot; and fold the answer back into the skill. Ship each skill with an owner and a separate reviewer (repeat) (<a href="https://www.youtube.com/watch?v=EaOit1mmR9g&amp;t=650s" target="_blank" rel="noopener">10:50</a>–<a href="https://www.youtube.com/watch?v=EaOit1mmR9g&amp;t=747s" target="_blank" rel="noopener">12:27</a>)</li></ul><div class="sh">Where Range is now</div><ul><li><strong>24 skills, 17 in planning:</strong> Six to eight months in, the skills are built by planners, marketers and member success staff. A Slack agent, Ranger, now helps everyone in the company. Specialists such as the insurance or CPA team own their own skills (<a href="https://www.youtube.com/watch?v=EaOit1mmR9g&amp;t=747s" target="_blank" rel="noopener">12:27</a>–<a href="https://www.youtube.com/watch?v=EaOit1mmR9g&amp;t=868s" target="_blank" rel="noopener">14:28</a>)</li><li><strong>The bottleneck has moved:</strong> The open question is who tests and updates every skill. He expects planners to become agent managers, aiming for advice to 100 people a day per planner instead of 3–4 (<a href="https://www.youtube.com/watch?v=EaOit1mmR9g&amp;t=868s" target="_blank" rel="noopener">14:28</a>–<a href="https://www.youtube.com/watch?v=EaOit1mmR9g&amp;t=969s" target="_blank" rel="noopener">16:09</a>)</li></ul></div></article><article class="it full" id="v-P5QCrpdr9gU" data-title="Claude Code Is Wasting Tokens... Microsoft Built a Fix" data-channel="Better Stack" data-verdict="worth"><a class="th" href="https://www.youtube.com/watch?v=P5QCrpdr9gU" target="_blank" rel="noopener"><img src="'+d+'" srcset="'+x+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">Better Stack</span><span class="chip warn">repeat</span><span class="chip v-worth">worth</span><h3><a href="https://www.youtube.com/watch?v=P5QCrpdr9gU" target="_blank" rel="noopener">Claude Code Is Wasting Tokens... Microsoft Built a Fix</a></h3><div class="meta">Better Stack · Josh, Better Stack (on Microsoft Research and UC Berkeley&#39;s TokenEconomizer) · uploaded 8 Nov, 5:45 PM IST · 7:35</div><div class="verdict v-worth"><b>Verdict:</b> worth watching if you spend a lot on Claude Code or Codex in one main repo — short, with a clear mechanism and published numbers; skip otherwise.</div><div class="repeat">🔁 Repeat: &#39;token costs / AI spend&#39; — seen 23 times before (Better Stack has covered several Claude Code token savers, e.g. Context Mode and &quot;These 5 Words Cost 12%&quot;). New here: an agent-agnostic plugin that learns from past sessions in a repo instead of compressing prompts.</div><div class="sh">What it is</div><ul><li><strong>The claim:</strong> TokenEconomizer is a free, open-source plugin from Microsoft Research and UC Berkeley that cut coding agent costs by 18–31% in tests without changing the model or agent. It works with Claude Code, Codex, GitHub Copilot CLI and Pi (<a href="https://www.youtube.com/watch?v=P5QCrpdr9gU&amp;t=0s" target="_blank" rel="noopener">0:00</a>–<a href="https://www.youtube.com/watch?v=P5QCrpdr9gU&amp;t=70s" target="_blank" rel="noopener">1:10</a>)</li><li><strong>Setup:</strong> Clone the repo and install the plugin from the marketplace, and keep the cloned folder because the plugin runs from there. A status command shows what it has learned and the costs tracked. Micro-skills are off by default and have to be turned on, and everything it learns stays local (<a href="https://www.youtube.com/watch?v=P5QCrpdr9gU&amp;t=70s" target="_blank" rel="noopener">1:10</a>–<a href="https://www.youtube.com/watch?v=P5QCrpdr9gU&amp;t=170s" target="_blank" rel="noopener">2:50</a>)</li></ul><div class="sh">The three techniques</div><ul><li><strong>Micro-skills:</strong> It learns repo facts from past sessions, such as which test command works, the env vars needed and where files live. Once confirmed enough times, these are given to the agent at the start of a new session so it doesn&#39;t repeat the same failed attempts (<a href="https://www.youtube.com/watch?v=P5QCrpdr9gU&amp;t=170s" target="_blank" rel="noopener">2:50</a>–<a href="https://www.youtube.com/watch?v=P5QCrpdr9gU&amp;t=229s" target="_blank" rel="noopener">3:49</a>)</li><li><strong>Tool pruning:</strong> Tool definitions cost tokens even when unused. It tracks which tools are actually used in a repo, stops loading the ones that never are, and lets you restore them (<a href="https://www.youtube.com/watch?v=P5QCrpdr9gU&amp;t=229s" target="_blank" rel="noopener">3:49</a>–<a href="https://www.youtube.com/watch?v=P5QCrpdr9gU&amp;t=252s" target="_blank" rel="noopener">4:12</a>)</li><li><strong>Failure-loop intervention:</strong> When the agent keeps rerunning nearly the same failing command, a judge model checks it, nudges the agent to try another approach, and if that fails tells you how to stop the turn (<a href="https://www.youtube.com/watch?v=P5QCrpdr9gU&amp;t=252s" target="_blank" rel="noopener">4:12</a>–<a href="https://www.youtube.com/watch?v=P5QCrpdr9gU&amp;t=293s" target="_blank" rel="noopener">4:53</a>)</li></ul><div class="sh">Results and fit</div><ul><li><strong>SWE-bench numbers:</strong> On 277 SWE-bench tasks across 6 repos and 5 agent/model combinations, average cost fell 18.4% to about 31%, counting the plugin&#39;s own model calls. Task success improved in 4 of 5 combinations and dipped slightly in one, and it was cheaper in all 30 repo/agent combinations (<a href="https://www.youtube.com/watch?v=P5QCrpdr9gU&amp;t=293s" target="_blank" rel="noopener">4:53</a>–<a href="https://www.youtube.com/watch?v=P5QCrpdr9gU&amp;t=325s" target="_blank" rel="noopener">5:25</a>)</li><li><strong>Who it helps:</strong> First released in October. Savings come from repeated work on the same repo, so it won&#39;t help if you hop between projects. Each agent learns separately, so Claude Code&#39;s learnings don&#39;t carry to Codex. His advice is to run it for a week on your main repo and compare similar tasks (<a href="https://www.youtube.com/watch?v=P5QCrpdr9gU&amp;t=325s" target="_blank" rel="noopener">5:25</a>–<a href="https://www.youtube.com/watch?v=P5QCrpdr9gU&amp;t=455s" target="_blank" rel="noopener">7:35</a>)</li></ul></div></article></div>',1))])}const j=u(E,[["render",D]]);export{Q as __pageData,j as default};
